from django.views import View
from django.http import JsonResponse, HttpResponseForbidden
from .models import TenantSessionNotification

class AccountFlashNotificationQueueView(View):
    def get(self, request):
        if not request.user.is_authenticated:
            return HttpResponseForbidden("Login required")

        # Force query to use the authenticated user's verified account ID
        account_id = request.user.account_id
        notifications = TenantSessionNotification.objects.filter(
            account_id=account_id,
            delivered=False
        )
        data = [{'id': n.id, 'toast_type': n.level, 'payload': n.data} for n in notifications]
        return JsonResponse({'account_id': account_id, 'pending_notifications': data})
